import { PHONE, PHONE_TEL, SITE_URL } from "../lib/data";
import { srcsetFor, heroSizesFor, heroDimsFor, bodyDimsFor, BODY_SIZES } from "../lib/imageVariants";
import Segments from "./Segments";
import SiteSchema from "./SiteSchema";

// Full-content page renderer: every visible word comes from the page's own
// Google Doc tab (lib/pages-full.js, generated by qa/parse-tabs.py).
// NOTHING here is invented:
// - hero eyebrow / H1 / intro / buttons = the tab's Eyebrow / H1 / intro /
//   CTA Button 1 + 2 lines. Button 1 carries ONLY the phone number.
// - sections = the tab's H2 sections in order; FAQ sections render as
//   <details> items (same pattern as the homepage FAQ).
// - the closing H2 section renders as the final-CTA band. Pages whose last
//   H2 is NOT a closing section (Contact, FAQ-last blogs) get a CTA-only
//   band from the tab's closing "CTA Button:" line.
// - heroImage null = new route with NO photo in this rebuild (per brief):
//   the hero renders on the navy background with no .hero-media div.
// - the old builder-added "Need help now?" note box is GONE (not doc text).

function plainText(parts) {
  return parts
    .map((p) => (typeof p === "string" ? p : p.link))
    .join("");
}

function faqPairs(section) {
  const pairs = [];
  let current = null;
  for (const b of section.blocks) {
    if (b.type === "h3") {
      current = { q: b.text, answers: [] };
      pairs.push(current);
    } else if (b.type === "p" && current) {
      current.answers.push(b.parts);
    }
  }
  return pairs;
}

function SectionBlocks({ blocks }) {
  return (
    <>
      {blocks.map((b, i) => {
        if (b.type === "p") {
          return (
            <p key={i}>
              <Segments parts={b.parts} />
            </p>
          );
        }
        if (b.type === "h3") {
          return <h3 key={i}>{b.text}</h3>;
        }
        if (b.type === "ul") {
          return (
            <ul className="check-list" key={i}>
              {b.items.map((it, j) => (
                <li key={j}>
                  {it.label ? (
                    <>
                      <strong>{it.label}:</strong>{" "}
                      <Segments parts={it.parts} />
                    </>
                  ) : (
                    <Segments parts={it.parts} />
                  )}
                </li>
              ))}
            </ul>
          );
        }
        if (b.type === "meta") {
          return (
            <p key={i}>
              <strong>{b.label}:</strong>{" "}
              {b.label === "Phone" ? (
                <a href={PHONE_TEL}>{b.text}</a>
              ) : (
                b.text
              )}
            </p>
          );
        }
        return null;
      })}
    </>
  );
}

export default function LinkedPage({ page, urlPath }) {
  const serviceSchema =
    page.kind === "service"
      ? {
          "@context": "https://schema.org",
          "@type": "Service",
          "@id": SITE_URL + urlPath + "#service",
          name: page.h1,
          description: page.metaDescription,
          // OPT-C2 SCHEMA-2 (2026-11-13): image = the page's own hero URL
          // (honest, already on-page as og:image) — nothing invented.
          image: page.heroImage ? SITE_URL + page.heroImage : undefined,
          provider: { "@id": SITE_URL + "/#localbusiness" },
          areaServed: { "@type": "City", name: "Elyria" },
          url: SITE_URL + urlPath,
        }
      : null;

  const breadcrumbSchema = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    "@id": SITE_URL + urlPath + "#breadcrumb",
    itemListElement: [
      { "@type": "ListItem", position: 1, name: "Home", item: SITE_URL },
      { "@type": "ListItem", position: 2, name: page.h1, item: SITE_URL + urlPath },
    ],
  };

  const webPageSchema = {
    "@context": "https://schema.org",
    // OPT-C3 SCHEMA-3a (2026-11-16): AboutPage / ContactPage subtypes —
    // the pages ARE the about and contact pages (doc tabs "About Our
    // Elyria Water Damage Restoration Crew" / "Contact Our Elyria Water
    // Damage Crew", routes /about, /contact) — nothing invented.
    // OPT-C3 SCHEMA-3b (2026-11-16): inLanguage "en" — doc is English,
    // <html lang="en"> already declares it.
    "@type":
      page.kind === "about"
        ? "AboutPage"
        : page.kind === "contact"
          ? "ContactPage"
          : "WebPage",
    "@id": SITE_URL + urlPath,
    url: SITE_URL + urlPath,
    name: page.h1,
    // OPT-C4 FIX-2 O-2 (2026-11-16): description = the page's own verbatim
    // doc meta description (already in <meta name="description">) — nothing
    // invented.
    description: page.metaDescription,
    inLanguage: "en",
    // OPT-C2 SCHEMA-2 (2026-11-13): primaryImageOfPage = the page's own
    // hero URL (honest, already on-page as og:image) — nothing invented.
    primaryImageOfPage: page.heroImage ? SITE_URL + page.heroImage : undefined,
    isPartOf: { "@id": SITE_URL + "/#website" },
    about: { "@id": SITE_URL + "/#localbusiness" },
    breadcrumb: { "@id": SITE_URL + urlPath + "#breadcrumb" },
  };

  // FAQPage from every FAQ section on the page (Q/A verbatim from the tab).
  const faqSections = page.sections.filter((s) => s.faq);
  const faqPairsAll = faqSections.flatMap((s) => faqPairs(s));
  const faqSchema =
    faqPairsAll.length > 0
      ? {
          "@context": "https://schema.org",
          "@type": "FAQPage",
          "@id": SITE_URL + urlPath + "#faq",
          mainEntity: faqPairsAll.map((f) => ({
            "@type": "Question",
            name: f.q,
            acceptedAnswer: {
              "@type": "Answer",
              text: f.answers.map((a) => plainText(a)).join(" "),
            },
          })),
        }
      : null;

  // HowTo for a tab with a numbered process ("The 10 Steps" — first-steps blog).
  const stepsSection = page.sections.find((s) => s.h2 === "The 10 Steps");
  const howToSchema = stepsSection
    ? {
        "@context": "https://schema.org",
        "@type": "HowTo",
        "@id": SITE_URL + urlPath + "#howto",
        name: stepsSection.h2,
        step: faqPairs(stepsSection).map((st, i) => ({
          "@type": "HowToStep",
          position: i + 1,
          name: st.q,
          text: st.answers.map((a) => plainText(a)).join(" "),
        })),
      }
    : null;

  // BlogPosting — blog pages ONLY (page.kind === "blog"). Headline is the
  // page H1 verbatim from its doc tab; mainEntityOfPage is the page URL
  // (no-slash form). Publisher / isPartOf / about reference ONLY @ids that
  // already exist in components/SiteSchema.js — nothing invented.
  // NO dates: the doc has none.
  // OPT-C1 SCHEMA-1 (2026-11-13): image = the blog's own hero image URL
  // (honest, on-page) and author = the site's own brand Organization,
  // via the existing #localbusiness @id — no person name, nothing invented.
  // OPT-C4 FIX-2 O-3 (2026-11-16): author name aligned to the canonical
  // LocalBusiness name "Water Damage Restoration Elyria" (was the header
  // variant "Elyria Water Damage"; same @id, #localbusiness).
  const blogPostingSchema =
    page.kind === "blog"
      ? {
          "@context": "https://schema.org",
          "@type": "BlogPosting",
          "@id": SITE_URL + urlPath + "#blogposting",
          headline: page.h1,
          description: page.metaDescription,
          // OPT-C3 SCHEMA-3b (2026-11-16): inLanguage "en" — doc is
          // English, <html lang="en"> already declares it.
          inLanguage: "en",
          image: page.heroImage ? SITE_URL + page.heroImage : undefined,
          author: {
            "@type": "Organization",
            "@id": SITE_URL + "/#localbusiness",
            name: "Water Damage Restoration Elyria",
          },
          mainEntityOfPage: SITE_URL + urlPath,
          publisher: { "@id": SITE_URL + "/#localbusiness" },
          isPartOf: { "@id": SITE_URL + "/#website" },
          about: { "@id": SITE_URL + "/#localbusiness" },
        }
      : null;

  const closingSection = page.sections.find((s) => s.closing);
  const bodySections = page.sections.filter((s) => !s.closing);

  return (
    <>
      <SiteSchema />
      {serviceSchema ? (
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(serviceSchema) }}
        />
      ) : null}
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumbSchema) }}
      />
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(webPageSchema) }}
      />
      {faqSchema ? (
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(faqSchema) }}
        />
      ) : null}
      {howToSchema ? (
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(howToSchema) }}
        />
      ) : null}
      {blogPostingSchema ? (
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(blogPostingSchema) }}
        />
      ) : null}

      <section className="hero hero-inner-page">
        {page.heroImage ? (
          <div className="hero-media">
            <img src={page.heroImage} alt={page.heroAlt} width={heroDimsFor(page.heroImage)?.width} height={heroDimsFor(page.heroImage)?.height} fetchPriority="high" srcSet={srcsetFor(page.heroImage)} sizes={heroSizesFor(page.heroImage)} />
          </div>
        ) : null}
        <div className="hero-inner">
          <p className="eyebrow">{page.eyebrow}</p>
          <h1>{page.h1}</h1>
          {page.intro.map((p, i) => (
            <p className="hero-intro" key={i}>{p}</p>
          ))}
          <div className="hero-cta">
            <a className="btn btn-call" href={PHONE_TEL}>{PHONE}</a>
            {/* FIX 4000 A-6 (narrow, 2026-11-13): on /contact only, Button 2
                ("Request a Call Back", doc tab 28) anchors to the new contact
                form on the same page. Every other Button 2 stays tel:. */}
            <a className="btn btn-help" href={page.kind === "contact" ? "#contact-form" : PHONE_TEL}>{page.cta2}</a>
          </div>
        </div>
      </section>

      <div className="wrap">
        <p className="breadcrumb">
          <a href="/">Home</a> / {page.h1}
        </p>
      </div>

      {bodySections.map((section, si) => {
        // Text-image slot (design round): the builder wires page.bodyImages
        // as [{src, alt, sectionIndex, sticky}]. Empty today -> renders
        // exactly as before; nothing is invented here.
        const sectionImages = (page.bodyImages || []).filter(
          (im) => im.sectionIndex === si
        );
        const mediaImage = sectionImages[0] || null;
        const extraImages = sectionImages.slice(1);
        return section.faq ? (
          <section className="section section-alt" id="faq" key={si}>
            <div className="wrap">
              <div className="section-head">
                <h2>{section.h2}</h2>
              </div>
              <div className="faq-list">
                {faqPairs(section).map((f) => (
                  <details className="faq-item" key={f.q} open>
                    <summary>
                      <h3>{f.q}</h3>
                    </summary>
                    <div className="faq-answer">
                      {f.answers.map((a, ai) => (
                        <p key={ai}>
                          <Segments parts={a} />
                        </p>
                      ))}
                    </div>
                  </details>
                ))}
              </div>
            </div>
          </section>
        ) : mediaImage ? (
          <section
            className={si % 2 === 1 ? "section section-alt" : "section"}
            key={si}
          >
            <div className="wrap prose">
              <div
                className={
                  "media-block" +
                  (si % 2 === 1 ? " flip" : "") +
                  (mediaImage.sticky ? " sticky" : "")
                }
              >
                <div className="media-img-wrap">
                  <img
                    className="media-img"
                    src={mediaImage.src}
                    alt={mediaImage.alt}
                    width={bodyDimsFor(mediaImage.src)?.width}
                    height={bodyDimsFor(mediaImage.src)?.height}
                    loading="lazy"
                    srcSet={srcsetFor(mediaImage.src)}
                    sizes={BODY_SIZES}
                  />
                </div>
                <div className="media-text">
                  <h2>{section.h2}</h2>
                  <SectionBlocks blocks={section.blocks} />
                </div>
              </div>
              {extraImages.map((im, ei) => (
                <div className="media-img-wrap" key={ei} style={{ marginTop: 28 }}>
                  <img
                    className="media-img"
                    src={im.src}
                    alt={im.alt}
                    width={bodyDimsFor(im.src)?.width}
                    height={bodyDimsFor(im.src)?.height}
                    loading="lazy"
                    srcSet={srcsetFor(im.src)}
                    sizes={BODY_SIZES}
                  />
                </div>
              ))}
            </div>
          </section>
        ) : (
          <section
            className={si % 2 === 1 ? "section section-alt" : "section"}
            key={si}
          >
            <div className="wrap prose">
              <h2>{section.h2}</h2>
              <SectionBlocks blocks={section.blocks} />
            </div>
          </section>
        );
      })}

      {/* FIX 4000 A-1 (2026-11-13): contact form, doc tab 28. Exactly the 5
          fields the doc orders — Name, Phone, Address, Describe the Water
          Damage, Submit — with proper <label>s. No invented fields, no added
          copy (the field names repeat the doc's own "Contact Form Fields"
          line, which still renders verbatim above in the Service Area
          section; qa/verify-rebuild.py treats the form as chrome for that
          reason). Static export has no handler: method POST to the same URL,
          no success messaging faked. */}
      {page.kind === "contact" ? (
        <section className="section">
          <div className="wrap prose">
            <form className="contact-form" id="contact-form" method="POST">
              <div className="field">
                <label htmlFor="contact-name">Name</label>
                <input id="contact-name" name="name" type="text" autoComplete="name" required />
              </div>
              <div className="field">
                <label htmlFor="contact-phone">Phone</label>
                <input id="contact-phone" name="phone" type="tel" autoComplete="tel" required />
              </div>
              <div className="field">
                <label htmlFor="contact-address">Address</label>
                <input id="contact-address" name="address" type="text" autoComplete="street-address" required />
              </div>
              <div className="field">
                <label htmlFor="contact-damage">Describe the Water Damage</label>
                <textarea id="contact-damage" name="describe-the-water-damage" required />
              </div>
              <button type="submit" className="btn btn-call">Submit</button>
            </form>
          </div>
        </section>
      ) : null}

      {closingSection ? (
        <section className="section final-cta">
          <div className="wrap">
            <h2>{closingSection.h2}</h2>
            <SectionBlocks blocks={closingSection.blocks} />
            <div className="hero-cta">
              <a className="btn btn-call" href={PHONE_TEL}>{PHONE}</a>
            </div>
          </div>
        </section>
      ) : (
        <section className="section final-cta">
          <div className="wrap">
            <div className="hero-cta">
              <a className="btn btn-call" href={PHONE_TEL}>{PHONE}</a>
            </div>
          </div>
        </section>
      )}
    </>
  );
}
